<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
const offset=ref(0),counts=ref<Record<string,number>>({}),total=ref(0);
const rows=ref<any[]>([]),token=ref(''),error=ref(''),busy=ref(false),loaded=ref(false),last=ref(''),info=ref<any>({}),timeline=ref<any[]>([]),knowledgeView=ref('all'),tab=ref('tasks'),selected=ref(''),events=ref<any[]>([]),creating=ref(false),days=ref('30'),filter=ref(''),knowledge=ref<any[]>([]),query=ref(''),migrations=ref<any[]>([]),preview=ref<any>(null),approvalDigest=ref(''),claim=ref<any>(null),artifact=ref(''),notice=ref('');
const form=ref({title:'',type:'bug',goal:'verified',target:'',scope:'',acceptance:'',ui:false,ux:false,preset:''});
const edit=ref(''),result=ref('{"status":"pass","summary":"","artifacts":[]}'),reason=ref(''),actor=ref('dashboard-user'),refs=ref(''),ack=ref(false);
const columns=[['active','正在推进','有效执行中的任务'],['pending','待处理','就绪、交接与等待环境'],['confirmation','待确认','准确版本上的决定'],['completed','最近完成','达到声明的交付目标'],['cancelled','已取消','保留结果与取消原因']];
const task=computed(()=>rows.value.find(r=>r.task.definition.id===selected.value));
const shown=computed(()=>rows.value.filter(r=>{const d=r.task.definition;if(filter.value&&!`${d.title} ${d.id} ${d.type}`.toLowerCase().includes(filter.value.toLowerCase()))return false;if(r.board==='completed'&&days.value!=='all')return r.task.completed&&Date.now()-Date.parse(r.task.completed)<Number(days.value)*86400000;return true}));
async function api(path:string,body?:any){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${token.value}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(!r.ok){let m;try{m=(await r.json()).error}catch{m=`服务返回 ${r.status}`}throw new Error(m)}return r.json()}
async function refresh(){try{if(!token.value)token.value=(await(await fetch('/api/session')).json()).token;const [data,i]=await Promise.all([api('/api/tasks?limit=20&offset='+offset.value+'&days='+(days.value==='all'?'0':days.value)+'&q='+encodeURIComponent(filter.value)),api('/api/info')]);rows.value=data.items||data;counts.value=data.counts||{};total.value=data.total??rows.value.length;info.value=i;last.value=new Date().toLocaleTimeString('zh-CN');error.value='';loaded.value=true;if(selected.value)events.value=await api('/api/events?id='+selected.value)}catch(e){error.value=String(e)}}
async function action(name:string,extras:any={}){busy.value=true;try{const v=await api('/api/action',{action:name,id:selected.value,executor:actor.value,reason:reason.value,...extras});if(name==='claim')claim.value=v.attempt;notice.value=`已记录 · ${v.next_action}`;await refresh();return v}catch(e){error.value=String(e)}finally{busy.value=false}}
async function create(){busy.value=true;try{const f=form.value,v=await api('/api/tasks',{...f,scope:f.scope.split(',').filter(Boolean),acceptance:f.acceptance.split('\n').filter(Boolean),checks:[],priority:0});creating.value=false;selected.value=v.task.definition.id;await refresh()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function select(r:any){selected.value=r.task.definition.id;claim.value=null;artifact.value='';reason.value='';edit.value=JSON.stringify(r.task.definition,null,2);await refresh()}
async function submit(){try{if(await action('submit',{submission:{task:selected.value,attempt:claim.value.id,token:claim.value.token,key:crypto.randomUUID(),result:JSON.parse(result.value)}}))claim.value=null}catch(e){error.value=String(e)}}
async function changeTab(name:string){tab.value=name;try{if(name==='knowledge')knowledge.value=await api('/api/knowledge?q='+encodeURIComponent(query.value));if(name==='timeline')timeline.value=await api('/api/timeline');if(name==='migration'){const m=await api('/api/migrations');migrations.value=m.runs;preview.value=m.preview}}catch(e){error.value=String(e)}}
async function openArtifact(ref:string){try{const r=await fetch('/api/artifact?task='+encodeURIComponent(selected.value)+'&ref='+encodeURIComponent(ref),{headers:{Authorization:'Bearer '+token.value}});artifact.value=await r.text()}catch(e){error.value=String(e)}}
async function migrate(action:string,id=''){busy.value=true;try{const v=await api('/api/migrations',{action,id,approved_digest:approvalDigest.value});notice.value=JSON.stringify({action,state:v.state,valid:v.valid});await changeTab('migration');await refresh()}catch(e){error.value=String(e)}finally{busy.value=false}}
const knowledgeShown=computed(()=>knowledge.value.filter(k=>knowledgeView.value==='all'||(knowledgeView.value==='rejected'?k.status==='rejected':k.kind===knowledgeView.value)));
const stamp=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN'):'原时间未知';
let timer:ReturnType<typeof setInterval>;onMounted(async()=>{await refresh();timer=setInterval(refresh,2500)});onUnmounted(()=>clearInterval(timer));
</script>
<template><div class="shell"><aside class="sidebar"><a class="brand" href="/"><span class="mark">ael</span><span>Agent Engineering Loop</span></a><div class="workspace"><span class="eyebrow">本地工程</span><strong>{{info.project?.split('/').pop()||'AEL'}}</strong><small>{{info.config?.mode==='shadow'?'影子模式 · 只读预览':'活动工作区'}}</small></div><nav aria-label="主导航"><button v-for="[id,label,n] in [['tasks','任务工作台','01'],['knowledge','工程知识','02'],['timeline','演进时间线','03'],['migration','初始化与迁移','04']]" :class="{chosen:tab===id}" @click="changeTab(id)">{{n}} <span>{{label}}</span></button></nav><footer><i :class="['dot',{offline:error}]"></i>{{error?'连接或数据异常':'本机服务已连接'}}<small>v0.1.0 · 离线资源<br>更新于 {{last||'等待连接'}}</small></footer></aside>
<main><header><div><span class="eyebrow">AEL / {{tab.toUpperCase()}}</span><h1>{{tab==='tasks'?'让每一步都有依据':tab==='knowledge'?'工程知识与取舍':tab==='timeline'?'工程演进时间线':'初始化与迁移'}}</h1><p>从明确目标，到可复核的完成。</p></div><button v-if="tab==='tasks'" class="primary" @click="creating=!creating">＋ 创建任务</button><button v-else @click="changeTab(tab)">刷新</button></header>
<div v-if="error" role="alert" class="alert">数据异常或服务断开：{{error}} <button @click="refresh">重试</button><small>最后成功数据：{{last||'尚未加载'}}；不代表当前状态。</small></div><div v-if="notice" role="status" class="notice">{{notice}}</div><p v-if="!loaded&&!error" role="status">正在加载真实工作区…</p>
<section v-if="creating" class="creation"><h2>创建明确的工作项</h2><form @submit.prevent="create"><label>标题<input v-model="form.title" required placeholder="例如：修复接口重试时的重复写入"></label><div class="fields"><label>类型<select v-model="form.type"><option v-for="t in ['bug','feature','improvement','refactor','research','docs','chore']">{{t}}</option></select></label><label>交付目标<select v-model="form.goal"><option value="verified">验证通过的改动</option><option value="analysis">分析结论与证据</option><option value="merged">合并目标分支</option></select></label><label>预设<select v-model="form.preset"><option value="">自动选择</option><option v-for="p in ['fast','standard','strict','research']">{{p}}</option></select></label></div><label v-if="form.goal==='merged'">目标分支<input v-model="form.target" required placeholder="main"></label><label>影响路径（逗号分隔）<input v-model="form.scope"></label><label>验收条件（每行一条）<textarea v-model="form.acceptance" required rows="3"></textarea></label><div class="inline"><label><input type="checkbox" v-model="form.ui">视觉检查</label><label><input type="checkbox" v-model="form.ux">交互检查</label></div><small>未配置检查命令时，使用明确的人工验收；不会自动全绿。</small><button class="primary" :disabled="busy">创建并生成计划</button></form></section>
<template v-if="tab==='tasks'"><div class="toolbar"><label class="search">检索任务<input v-model="filter" placeholder="标题、ID 或类型" @input="offset=0;refresh()"></label><label>完成历史<select v-model="days" @change="offset=0;refresh()"><option value="7">最近 7 天</option><option value="30">最近 30 天</option><option value="all">全部历史 · 含未知时间</option></select></label><span>{{total}} 个工作项</span></div><div class="pagination"><button :disabled="offset===0" @click="offset=Math.max(0,offset-20);refresh()">上一页</button><small>各板块第 {{Math.floor(offset/20)+1}} 页 · 每页最多20项</small><button :disabled="!Object.values(counts).some(n=>n>offset+20)" @click="offset+=20;refresh()">下一页</button></div><div class="board"><section v-for="[id,title,sub] in columns" :key="id" class="column" :data-board="id"><div class="column-head"><h2><i :class="id"></i>{{title}}<span>{{counts[id]??shown.filter(r=>r.board===id).length}}</span></h2><p>{{sub}}</p></div><button v-for="r in shown.filter(x=>x.board===id)" :key="r.task.definition.id" class="task" @click="select(r)"><div class="card-meta"><span>{{r.task.definition.type}}</span><span>{{r.task.plan.preset}}</span></div><h3>{{r.task.definition.title}}</h3><p class="step">{{r.task.current_step}} <span>→ {{r.next_action}}</span></p><p v-if="r.board==='cancelled'" class="failure">取消：{{r.task.result}} · {{stamp(r.task.completed)}}</p><p v-if="r.task.failure" class="failure">{{r.task.failure}}</p><p v-for="b in r.blocking_reasons" class="failure">{{b}}</p><div class="card-bottom"><small>{{r.task.definition.id.slice(0,11)}}</small><span v-if="r.task.historical">{{r.task.status==='completed'?'历史完成 · 导入未复验':'旧任务 · 待恢复'}}</span><span v-else-if="r.board==='completed'">{{r.task.result}}</span><span v-else>修订 {{r.task.definition.definition_revision}}</span></div><small v-if="r.board==='completed'">{{stamp(r.task.completed)}}</small></button><div v-if="!shown.some(r=>r.board===id)" class="empty">{{(counts[id]||0)>0?'本页暂无，可翻页查看其余任务。':id==='pending'?'创建任务后，从这里开始。':'暂无'+title+'的任务'}}</div></section></div></template>
<section v-if="tab==='knowledge'"><div class="toolbar"><label class="search">中文、英文、路径或符号<input v-model="query" @keyup.enter="changeTab('knowledge')"></label><button @click="changeTab('knowledge')">搜索</button><label>知识视图<select v-model="knowledgeView"><option value="all">全部来源</option><option value="spec">架构与契约基线</option><option value="decision">决策清单</option><option value="rejected">避坑 · 被否决方案</option></select></label></div><div v-if="!knowledgeShown.length" class="large-empty">还没有匹配的知识。项目知识位于 .ael/knowledge，检索保留来源与状态。</div><article v-for="k in knowledgeShown" class="knowledge"><span class="tag">{{k.kind}} / {{k.status}}</span><h2>{{k.title}}</h2><p>{{k.reason}} · {{k.path}}</p><small>来源 {{k.id}} · {{k.hash?.slice(0,16)}}</small><pre>{{k.body}}</pre><p v-if="k.superseded_by">替代为 {{k.superseded_by}}</p></article></section>
<section v-if="tab==='timeline'"><div v-if="!timeline.length" class="large-empty">尚无已记录的工程事件。</div><article v-for="event in timeline" class="timeline-item"><time>{{stamp(event.at)}}</time><div><h2>{{event.kind}}</h2><p>{{event.task||event.body.title||event.body.id||'项目事件'}}</p><p v-if="event.kind==='knowledge_observed'">知识内容版本被观察 · {{event.body.kind}} / {{event.body.status}}；原决策日期不由导入时间推断。</p><details><summary>来源、版本与事件内容</summary><pre>{{JSON.stringify(event.body,null,2)}}</pre></details></div></article></section><section v-if="tab==='migration'"><div class="summary"><h2>项目与运行实例</h2><p>{{info.project}}</p><p>模式：{{info.config?.mode}} · Schema {{info.config?.schema}}</p><p>运行数据：{{info.data_dir}}</p></div><p>扫描与计划只盘点明确项目根。应用会导入资料；正式激活需单独 CLI 授权。</p><button :disabled="busy" @click="migrate('preview')">扫描与预览</button><section v-if="preview" class="preview"><h2>待审阅计划 · {{preview.sources.length}} 条来源</h2><p>确认摘要：<code>{{preview.digest}}</code></p><p>下列 pending 资料保留为冲突，不自动生效；preserve 项只备份，不执行。</p><details v-for="source in preview.sources" :key="source.id"><summary>{{source.action}} · {{source.path}} → {{source.target||'只读备份'}}</summary><p v-for="risk in source.risks" class="failure">{{risk}}</p><small>来源 SHA256 {{source.hash}}</small><pre>{{source.body}}</pre></details><label>审阅后填写完整确认摘要<input v-model="approvalDigest" placeholder="只批准当前内容版本"></label><button class="primary" :disabled="busy||approvalDigest!==preview.digest" @click="migrate('apply')">批准此计划并导入</button></section><div v-if="!migrations.length" class="large-empty">尚无迁移记录。运行 ael migrate scan --out &lt;报告目录&gt; 开始只读盘点。</div><article v-for="m in migrations" class="knowledge"><h2>迁移 {{m.id}}</h2><p>{{m.state}} · {{m.count}} 条来源</p><div class="actions"><button :disabled="busy" @click="migrate('verify',m.id)">核验迁移</button><button :disabled="busy||m.state==='rolled_back'" @click="migrate('repair',m.id)">修复中断</button><button :disabled="busy||m.state==='rolled_back'" @click="migrate('rollback',m.id)">回滚本次导入</button></div><p v-for="warning in m.warnings" class="failure">{{warning}}</p><details><summary>映射、风险与原文对照</summary><pre>{{JSON.stringify(m,null,2)}}</pre></details></article></section></main>
<aside v-if="task" class="detail" aria-label="任务详情"><button class="close" @click="selected=''">关闭 ×</button><span class="eyebrow">{{task.task.definition.id}}</span><h2>{{task.task.definition.title}}</h2><div class="inline"><span class="tag">{{task.task.current_step}}</span><span class="tag">{{task.next_action}}</span></div><p v-for="b in task.blocking_reasons" class="failure">{{b}}</p><h3>目标、范围与验收</h3><p>交付目标：{{task.task.definition.goal}}</p><p v-if="task.task.status!=='open'">结果：{{task.task.result}} · {{stamp(task.task.completed)}}</p><p>来源：{{task.task.definition.source||'直接创建'}}</p><p>范围：{{task.task.definition.scope?.join(', ')||'未限定路径'}}</p><p>非目标：{{task.task.definition.non_goals?.join(', ')||'无额外声明'}}</p><ul><li v-for="a in task.task.definition.acceptance">{{a}}</li></ul><h3>计划 · 修订 {{task.task.plan.revision}}</h3><p>{{task.task.plan.steps.join(' → ')}}</p><small>{{task.task.plan.reason}}</small><h3>下一动作</h3><label>执行者<input v-model="actor"></label><label>理由 / 人工验收结论<input v-model="reason"></label><label>产物相对路径（逗号分隔）<input v-model="refs" placeholder="report.md, screenshot.png"></label><div class="actions"><button :disabled="busy||task.next_action!=='continue'||task.task.current_step==='verify'" :title="task.next_action!=='continue'?'请先解决阻塞':'领取当前步骤'" @click="action('claim')">领取步骤</button><button :disabled="busy||task.task.status!=='open'" @click="action('pause')">暂缓</button><button :disabled="busy||task.task.status!=='open'" @click="action('cancel')">取消任务</button></div><label class="inline"><input type="checkbox" v-model="ack">我已核实旧执行进程停止</label><button :disabled="busy||task.task.status!=='open'" @click="action('resume',{ack_stopped:ack})">恢复 / 释放旧租约</button><div v-if="claim"><h3>提交当前 Attempt</h3><small>{{claim.id}}</small><label>StepResult JSON<textarea v-model="result" rows="5"></textarea></label><button class="primary" :disabled="busy" @click="submit">提交并查看下一步</button></div>
<div v-if="task.task.confirmation" class="confirmation"><h3>确认对应版本</h3><p>{{task.task.confirmation.reason}}</p><small>定义 {{task.task.confirmation.definition_revision}} · 计划 {{task.task.confirmation.plan_revision}}</small><div class="actions"><button v-for="[decision,label] in [['approve','批准'],['adjust','要求调整'],['reject','否决方案']]" :disabled="busy||!reason" @click="action('confirm',{kind:task.task.confirmation.kind,revision:task.task.confirmation.definition_revision,plan_revision:task.task.confirmation.plan_revision,candidate:task.task.confirmation.candidate,decision})">{{label}}</button></div></div>
<h3>检查与证据</h3><div v-for="c in task.task.definition.checks" class="check"><strong>{{c.id}} · {{c.kind}}</strong><small>{{c.covers?.join('；')}}</small><button :disabled="busy||task.task.current_step!=='verify'||task.next_action==='wait_confirmation'" @click="c.command?.length?action('verify',{unit:c.id}):action('review',{unit:c.id,artifacts:refs.split(',').map(x=>x.trim()).filter(Boolean)})">{{c.command?.length?'运行真实检查':'记录人工验收'}}</button></div><div v-for="e in task.task.evidence" class="evidence"><strong :class="e.result">{{e.check}} · {{e.result}}</strong><small>{{e.source}} · {{e.candidate.slice(0,16)}}</small><p>{{e.reason}}</p><small v-for="[ref,status] in Object.entries(e.artifact_status||{})">{{ref}} · {{status}}</small><button v-for="a in e.artifacts" @click="openArtifact(a)">{{a}}</button></div><pre v-if="artifact">{{artifact}}</pre><details><summary>Attempt、候选与交付详情</summary><pre>{{JSON.stringify({attempts:task.task.attempts,candidate:task.task.candidate,delivery:task.task.delivery,dependencies:task.task.definition.dependencies,knowledge:task.task.definition.knowledge,feedback:task.task.feedback},null,2)}}</pre></details><details><summary>编辑任务定义（生成新修订）</summary><textarea v-model="edit" rows="12"></textarea><button :disabled="busy||!reason||task.task.status!=='open'" @click="action('edit',{definition:JSON.parse(edit)})">提交定义修订</button></details><h3>真实时间线</h3><ol class="events"><li v-for="e in events"><strong>{{e.kind}}</strong><small>{{stamp(e.at)}}</small><details><summary>事件内容</summary><pre>{{JSON.stringify(e.body,null,2)}}</pre></details></li></ol></aside></div></template>
